toolArgs.file_text:
@namespace sv_75bba0a13337491a9558543d0125dbc8.Components.Pages.Settings
@using sv_75bba0a13337491a9558543d0125dbc8.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <label><strong>Theme</strong></label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="theme" value="Light" @onchange="() => _theme = &quot;Light&quot;" checked="@(_theme == "Light")" />
                    <span>Light</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="Dark" @onchange="() => _theme = &quot;Dark&quot;" checked="@(_theme == "Dark")" />
                    <span>Dark</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="theme" value="System" @onchange="() => _theme = &quot;System&quot;" checked="@(_theme == "System")" />
                    <span>System</span>
                </label>
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label><strong>Font Size</strong></label>
            <div class="radio-group">
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Small" @onchange="() => _fontSize = &quot;Small&quot;" checked="@(_fontSize == "Small")" />
                    <span>Small</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Medium" @onchange="() => _fontSize = &quot;Medium&quot;" checked="@(_fontSize == "Medium")" />
                    <span>Medium</span>
                </label>
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="Large" @onchange="() => _fontSize = &quot;Large&quot;" checked="@(_fontSize == "Large")" />
                    <span>Large</span>
                </label>
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language"><strong>Language</strong></label>
            <select id="language" @bind="_language" class="form-control">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
                <option value="zh">Chinese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="form-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" class="toggle-switch" />
                <span><strong>Compact Mode</strong></span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p>The quick brown fox jumps over the lazy dog.</p>
            <button class="btn btn-primary">Sample Button</button>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message @(_isError ? "toast-error" : "toast-success")">
                @_message
            </div>
        }
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private string _message = "";
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _isError = true;
        }
    }
}

@page "/settings"
@namespace sv_75bba0a13337491a9558543d0125dbc8.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

::deep .settings-sidebar {
    width: 240px;
    background: var(--bs-gray-100, #f8f9fa);
    border-right: 1px solid var(--bs-gray-300, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

::deep .settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
    color: var(--bs-gray-700, #495057);
}

::deep .settings-nav-item:hover {
    background: var(--bs-gray-200, #e9ecef);
}

::deep .settings-nav-item.active {
    background: var(--bs-primary-bg-subtle, #cfe2ff);
    border-left-color: var(--bs-primary, #0d6efd);
    color: var(--bs-primary, #0d6efd);
    font-weight: 600;
}

::deep .settings-nav-icon {
    font-size: 1.2rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

::deep .settings-section h2 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--bs-gray-300, #dee2e6);
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
}

::deep .form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--bs-gray-300, #dee2e6);
    border-radius: 0.375rem;
    font-size: 1rem;
    line-height: 1.5;
}

::deep .form-control:focus {
    border-color: var(--bs-primary, #0d6efd);
    outline: 0;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

::deep .form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.875rem;
    font-weight: 500;
    transition: background-color 0.15s;
}

::deep .btn-primary {
    background: var(--bs-primary, #0d6efd);
    color: white;
}

::deep .btn-primary:hover {
    background: #0b5ed7;
}

::deep .btn-secondary {
    background: var(--bs-gray-500, #6c757d);
    color: white;
}

::deep .btn-secondary:hover {
    background: #5c636a;
}

::deep .btn-danger {
    background: var(--bs-danger, #dc3545);
    color: white;
}

::deep .btn-danger:hover {
    background: #bb2d3b;
}

::deep .btn-sm {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
}

::deep .toast-message {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
}

::deep .toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

::deep .toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Avatar */
::deep .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: var(--bs-gray-100, #f8f9fa);
    border-radius: 0.5rem;
}

::deep .avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    background: var(--bs-gray-300, #dee2e6);
}

::deep .avatar-url {
    font-size: 0.8rem;
    color: var(--bs-gray-600, #6c757d);
    word-break: break-all;
    margin: 0;
}

/* Toggles */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
